#!/usr/bin/env python3
"""Build an offline Persian guide. No remote assets, no database access."""
from pathlib import Path
import json, html, base64, collections
R=Path(__file__).resolve().parents[1]
esc=html.escape
scope=json.loads((R/'scope.json').read_text()); decisions=json.loads((R/'prisma/decisions.json').read_text()); selected=json.loads((R/'sources/selected-data-map.json').read_text())
sections=[]
def code(s,lang='shell'):
    return '<div class="code"><span>'+lang+'</span><button class="copy" type="button">کپی</button><pre dir="ltr"><code>'+esc(s.strip())+'</code></pre></div>'
def section(title,body): sections.append((title,body))
def table(head,rows): return '<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def alert(text):return '<aside class="warning">'+text+'</aside>'
def checklist(items):return '<ul class="checks">'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
section('قبل از شروع: دقیقاً چه چیزی می‌سازیم؟', '''<p>این دفترچه مسیر ساخت یک <strong>بک‌اند آزمایشی مستقل</strong> است؛ نه مهاجرت ERP فعلی به Nest و نه ساخت تمام Data Map. خروجی اولیهٔ دستورها: monorepo، Schema محدود، اتصال Prisma، health check، پوستهٔ React و تست‌های منطق نمونه است. APIهای تجاری فصل‌های بعد قرارداد و دستور ساخت‌اند و هنوز سرویس آماده نیستند.</p>'''+table(['داخل محدوده','خارج محدوده'],[
['محصول، قطعه، کامپوننت؛ تأمین‌کننده و منابع تأمین موردنیاز مواد','مالی، فروش، خزانه، همکاری و داشبورد عمومی ERP'],
['BOM و محاسبهٔ نیاز مواد و snapshotهای آن','سفارش خرید/رسید، گردش کامل انبار، سفارش تولید و مراکز کاری'],
['بازرگانی: ثبت اولیهٔ پروژه و سربرگ ثبت سفارش تا مرحلهٔ فعلی','اقلام/مجوز سفارش، FX، بیمه، حمل، گمرک، تعهد، هزینه و مراحل آینده'],
['مرجع واحد/ارز/کشور و ارجاع مسئول/مالک فقط در حد نیاز','ماژول کامل مدیریت هویت، سازمان، کارت و پروانهٔ بازرگانی'],
['React فقط صفحهٔ وضعیت اتصال','هیچ صفحهٔ عملیاتی محصولات، BOM، MRP، تأمین‌کننده یا بازرگانی']])+alert('۴۲ مدل به معنی ۴۲ صفحه یا ۴۲ قابلیت جدید نیست: ۲۹ جدول دامنه/ورودی و خروجی snapshot + ۱۳ جدول پشتیبان. انتخاب صریح در <code>scope.json</code> است؛ انتخاب کل schema یا گسترش خودکار از روی FK ممنوع است.'))
section('ساختار جدید؛ اپ قبلی کجا رفت؟',code('''hadron/
  .git/                       # همان Git؛ جابه‌جا نشده
  README.md
  run-hadron.bat               # ارجاع به لانچر داخل main-erp
  main-erp/                   # همهٔ کار قبلی، .NET / EF / React
    src/  tests/  scripts/  docs/  output/
  nx-erp-lab/
    implementation-guide.html # همین دفترچه
    scope.json                # مرز مجاز مدل‌ها
    sources/                  # دو HTML اصلی، بدون تغییر
    prisma/                   # Schema + تصمیم‌ها + SQL مکمل
    recipe/                   # فایل‌های قابل کپی روی scaffold جدید
    tools/                    # مولدها؛ بدون اتصال به DB
    workspace/                # خودت در فصل ۶ می‌سازی؛ هنوز تحویل اپ نیست''','layout')+'''<p>تمام دستورهای قبلی ERP را پس از <code>cd main-erp</code> اجرا کن. runtime اپ قبلی Node 26.x است؛ آزمایش جدید با Node 22.22.3 بررسی شده. فایل‌های محلی ignored مانند <code>.env</code> روی کامپیوتر تو با pull جابه‌جا نمی‌شوند؛ آن‌ها را با حفظ نسخهٔ قبلی در مسیر درست تنظیم کن. volumeهای قبلی را حذف نکن.</p><p>۵۹۵ فایل پیش از انتقال SHA256 شدند؛ در لحظهٔ انتقال همه در مسیر جدید برابر بودند. پس از آن فقط helperهای بستهٔ انتقال و مستند مسیر آن عمداً با چیدمان جدید سازگار شدند. اجرای واقعی این helperهای ویندوز در این محیط بررسی نشده است.</p>''')
section('منبع Schema و سطح اطمینان', '''<p>منبع ساختاری <code>sources/hadron-data-map.html</code> و JSON داخلی <code>hadron-model</code> است. فایل <code>erp-monorepo-guide.html</code> فقط الگوی دفترچه است، نه مدل عمومی مالی/فروش آن. هیچ کدام از دو اصل بازنویسی نشده‌اند.</p>'''+table(['منبع / تصمیم','معنا'],[
['Data Map: ۱۸۰ جدول → allowlist: ۴۲ جدول / ۵۳۷ ستون','نام جدول و ستون، PK و FK صریح از منبع انتخاب شده‌اند. بقیهٔ ۱۳۸ جدول وارد Schema نشده‌اند.'],
['EF snapshot فقط شاهد تکمیلی legacy','فقط nullable، max length، precision و index/check ستون موجود در Map را تکمیل می‌کند؛ هیچ جدول یا ستون EF-only اضافه نمی‌شود.'],
['۵ nullable نامعلوم + ۵ precision پیشنهادی','nullable نامعلوم موقتاً nullable و precision صریح آزمایش است. قبل از migration تصمیم تجاری لازم است؛ این‌ها حقیقت قطعی منبع نیستند.'],
['شناسهٔ Trading و FKهای آن → UUID','نرمال‌سازی آزمایش جدید، نه تبدیل درجا روی دیتابیس ERP. تغییر نام و نوع‌ها در decisions.json ثبت شده‌اند.'],
['enum سفارش: قرارداد فعلی، نه آینده','DRAFT / SUBMITTED / ACTIVE / SUSPENDED / CANCELLED؛ تفاوت با CONFIRMED/EXPIRED منبع به‌عنوان overlay صریح ثبت شده.'],
['partial unique indexes و checkها','Prisma همه را مدل نمی‌کند. فایل‌های legacy-indexes.sql و legacy-checks.sql پس از بازبینی به migration اولیه افزوده می‌شوند.']])+'''<p>نام مدل Prisma برای جلوگیری از برخورد، schema-prefixed است: <code>CatalogItems</code> → <code>prisma.catalogItems</code>؛ نام فیزیکی با <code>@@map</code> و <code>@@schema</code> حفظ شده. <code>products.ItemId</code> همان PK/FK مشترک است، نه یک Id جدید.</p><p class="muted">SHA256 منبع: <bdi>'''+decisions['sourceSha256']+'''</bdi></p><button id="download-schema">دانلود Schema از داخل همین HTML</button> <a href="prisma/decisions.json">همهٔ تصمیم‌ها</a> · <a href="scope.json">محدودهٔ صریح</a>''')
section('معماری و مالکیت داده', '''<p>جریان: React shell → <code>/api</code> با proxy همان origin → NestJS → Prisma 7 + pg adapter → PostgreSQL مستقل. مرورگر نباید برای API از <code>localhost</code> استفاده کند؛ localhost مقصد proxy فقط روی سرور توسعه است.</p>'''+table(['لایه','مسئولیت'],[['controller + DTO','فقط transport، اعتبارسنجی ورودی، مجوز؛ بدون محاسبهٔ BOM یا تغییر مستقیم Prisma از body'],['application service','هماهنگی transaction، resolve مرجع فعال، version، audit و persistence'],['domain functions','قواعد خالص قابل تست؛ decimal دقیق، cycle detection و وضعیت‌ها'],['Prisma / PostgreSQL','FK، unique، check، قفل ردیف و atomicity؛ جایگزین قواعد کسب‌وکار نیست'],['reference adapters','واحد، ارز، مالک و مسئول. اطلاعات داخلی کاربر/رمز را به قرارداد lookup نده'],['React','فقط health check؛ توکن آزمایش را داخل bundle یا VITE_* نگذار']])+alert('جداسازی دیتابیس واقعی است: compose project برابر hadron-nx-lab، پورت 5544، دیتابیس hadron_nx_lab و volume برابر hadron-nx-lab-pg. main-erp همچنان پروژه و volumeهای قبلی خودش را دارد.'))
section('پیش‌نیاز و نسخه‌ها',code('''node --version
npm --version
git --version
docker --version
docker compose version''')+'''<p>Node بررسی‌شده: <strong>22.22.3</strong>؛ npm 10.9.8؛ Docker Desktop / Compose v2 لازم است. ابزار Docker و .NET در محیط بررسی موجود نبودند؛ نصب و اجرای DB این راهنما روی سیستم تو انجام می‌شود.</p>'''+table(['ابزار','نسخه / دلیل'],[['Nx و pluginها','23.3.0، همه هم‌نسخه'],['Nest','11.x که generator همین نسخهٔ Nx تولید می‌کند؛ Nest 12 را جداگانه نصب نکن'],['Prisma / client / adapter-pg','هر سه 7.10.1؛ از latest استفاده نکن چون می‌تواند RC باشد'],['PostgreSQL','18؛ در محیط آزمایش جدا'],['React / Vite / TypeScript','generator سازگار تولید می‌کند؛ package-lock.json ساخته‌شده را نگه دار و سپس npm ci استفاده کن']])+alert('نسخه‌های وابستگی‌ها audit پاک تضمین نشده‌اند. در scaffold بررسی‌شده هشدارهای dependency audit وجود داشت؛ پیش از انتشار، npm audit را بررسی کن. اجرای کور npm audit fix --force توصیه نمی‌شود.'))
section('ساخت monorepo — دستورهای بررسی‌شده', '''<p>از ریشهٔ clone دریافت‌شده شروع کن. این دستورها در PowerShell و Bash قابل استفاده‌اند. <code>workspace</code> باید هنوز وجود نداشته باشد. اگر از قبل وجود دارد، دوباره generator را روی کار خودت اجرا نکن.</p>'''+code('''cd nx-erp-lab
npx --yes create-nx-workspace@23.3.0 workspace --preset=apps --workspaceType=integrated --packageManager=npm --nxCloud=skip --interactive=false --skipGit=true
cd workspace
npx nx add @nx/nest@23.3.0 --interactive=false
npx nx add @nx/react@23.3.0 --interactive=false
npx nx g @nx/nest:application apps/api --name=api --unitTestRunner=jest --e2eTestRunner=none --strict --useProjectJson --interactive=false
npx nx g @nx/react:application apps/web --name=web --bundler=vite --unitTestRunner=none --e2eTestRunner=none --style=css --routing=false --useProjectJson --interactive=false
npx nx show project api
npx nx show project web''')+'''<p>دو پروژه با نام‌های دقیق <code>api</code> و <code>web</code> ساخته می‌شوند. <code>--skipGit=true</code> جلوی Git تودرتو را می‌گیرد؛ Git بیرونی مخزن باقی می‌ماند. فعلاً هیچ finance، sales، inventory یا business frontend generator اجرا نکن.</p>''')
section('نصب وابستگی و اعمال فایل‌های آماده',code('''npm install --save-exact @prisma/client@7.10.1 @prisma/adapter-pg@7.10.1 pg@8.23.1 dotenv@18.0.8 decimal.js@10.6.0 class-validator@0.15.1 class-transformer@0.5.1
npm install -D --save-exact prisma@7.10.1 @types/pg@8.23.1
node ../tools/apply-recipe.mjs --replace-scaffold''')+'''<p>همچنان داخل <code>nx-erp-lab/workspace</code> هستی. helper فقط فایل‌های tutorial را از <code>../recipe</code> و Schema محدود را کپی می‌کند؛ DB را اجرا نمی‌کند. flag یعنی اجازهٔ جایگزینی فایل scaffold تازه، نه جایگزینی کد توسعه‌یافتهٔ خودت. این کار برای workspace تازه است؛ روی پروژه‌ای که بعداً تغییر داده‌ای دوباره بدون diff اجرا نکن.</p>'''+checklist(['فایل‌های Prisma در <code>workspace/prisma/</code> و config در ریشهٔ workspace باشند.','فایل <code>apps/api/src/app/domain.logic.spec.ts</code> را ببین؛ تست خالص است نه اثبات DB.','فایل <code>apps/web/vite.config.mts</code> روی 0.0.0.0 و proxy نسبی تنظیم شده است.','<code>.env</code> و generated client نباید وارد Git شوند.']) )
section('تنظیمات امن؛ بدون secret ثابت',code('''node tools/init-env.mjs''')+'''<p>این دستور <code>.env</code> جدید با رمز و توکن تصادفی ۲۵۶بیتی می‌سازد؛ secret چاپ نمی‌کند و اگر فایل موجود باشد متوقف می‌شود. فایل قبلی را کورکورانه حذف نکن. از <code>main-erp/.env</code> استفاده نکن.</p>'''+table(['متغیر','کاربرد'],[['DATABASE_URL','فقط postgresql://…@127.0.0.1:5544/hadron_nx_lab؛ helper آدرس غیرمجاز را رد می‌کند'],['POSTGRES_USER / PASSWORD','فقط سرویس PostgreSQL همین آزمایش'],['LAB_API_TOKEN','دسترسی service-token موقت توسعه؛ هرگز در React، log یا URL قرار نده'],['PORT','3101 برای API؛ web روی 4201']])+alert('LabGuard، ورود کاربران و RBAC نیست. تمام مسیرها به‌صورت پیش‌فرض توکن می‌خواهند، health عمومی است، و توکن در NODE_ENV=production غیرفعال است. برای استفادهٔ چندکاربره، قبل از APIهای تجاری یک adapter هویت و مجوز معتبر لازم است؛ hashهای ASP.NET Identity را Argon2 فرض نکن و به دیتابیس اصلی وصل نشو.'))
section('PostgreSQL مستقل؛ بدون دست زدن به ERP',code('''docker compose -f compose.yml config --quiet
docker compose -f compose.yml up -d --wait postgres
docker compose -f compose.yml ps''')+'''<p>پورت <code>5544</code> فقط روی loopback میزبان DB منتشر می‌شود. اگر اشغال است ابتدا علت را بررسی کن؛ آن را به 5432 اپ اصلی تغییر نده. PostgreSQL 18 با volume روی <code>/var/lib/postgresql</code> تنظیم شده است.</p>'''+code('''docker compose -f compose.yml stop postgres
# برای ادامه بعداً:
docker compose -f compose.yml up -d --wait postgres''')+alert('از docker compose down -v استفاده نکن. اگر رمز .env را بعد از ساخته‌شدن volume عوض کنی، رمز داخلی PostgreSQL خودکار تغییر نمی‌کند؛ مشکل را با حذف volume اصلی یا کپی env قبلی حل نکن.'))
section('Prisma 7: validate و generate',code('''node --env-file=.env tools/db.mjs validate
node --env-file=.env tools/db.mjs generate''')+'''<p>URL در <code>prisma.config.ts</code> است، نه datasource داخل Schema. client با generator جدید <code>prisma-client</code> و <code>moduleFormat="cjs"</code> برای Nest تولید می‌شود؛ مسیر <code>apps/api/src/generated/prisma</code> را commit نکن. importFileExtension خالی است تا importهای TypeScript در build Nx درست resolve شوند.</p><p>Runtime از <code>new PrismaPg({connectionString})</code> استفاده می‌کند؛ نمونه‌های قدیمی Prisma 6 را با این دستورها مخلوط نکن. validate به معنی صحت منطق دامنه یا اجرای migration نیست.</p>''')
section('Migration اولیه؛ checkpoint اجباری بازبینی', '''<p>فقط روی دیتابیس تازه و مستقل آزمایش. ابتدا SQL را بساز، ولی هنوز deploy نکن:</p>'''+code('''node --env-file=.env tools/db.mjs migrate-create''')+'''<p>فایل <code>prisma/migrations/&lt;timestamp&gt;_initial_scoped_lab/migration.sql</code> را باز کن. باید فقط ۸ schema انتخاب‌شده، ۴۲ جدول و enumهایشان را داشته باشد؛ ساخت جدول finance/sales/production یا inventory.transactions نشانهٔ خطاست.</p>'''+checklist(['تمام ردیف‌های <code>UNKNOWN-nullability-nullable-in-lab</code> و <code>lab-explicit-precision-not-in-map</code> در decisions.json را تصمیم‌گیری کن.','SQL مکمل <code>prisma/legacy-checks.sql</code> و سپس <code>prisma/legacy-indexes.sql</code> را پس از DDL اولیه، با بازبینی به همان migration.sql اضافه کن؛ دوباره در اجرای بعدی append نکن.','سه partial unique: BOM تأییدشدهٔ والد، منبع تأمین ترجیحی فعال و تماس اصلی فعال؛ بدون آن‌ها race واقعی کنترل نمی‌شود.','برای Trading، unique شمارهٔ پروژه، unique سراسری orderNumber، مبلغ مثبت و version≥1 را اضافه کن؛ SQL نمونه پایین است.','SQL منبع، trigger، RLS، tenant policy و auditing خودکار کامل را توصیف نمی‌کند؛ Prisma به‌تنهایی این‌ها را ایجاد نکرده است.','در migration dev اگر prompt reset یا drift دیدی، توقف کن. helper عمداً reset و db push ندارد.'])+code('''ALTER TABLE trading.trade_projects
  ADD CONSTRAINT lab_project_number_unique UNIQUE ("projectNumber"),
  ADD CONSTRAINT lab_project_version_positive CHECK (version >= 1);
ALTER TABLE trading.order_registrations
  ADD CONSTRAINT lab_order_number_unique UNIQUE ("orderNumber"),
  ADD CONSTRAINT lab_order_amount_positive CHECK ("declaredValueAmount" > 0),
  ADD CONSTRAINT lab_order_version_positive CHECK (version >= 1);''','SQL — پس از بررسی نبود constraint تکراری')+code('''node --env-file=.env tools/db.mjs migrate-deploy
node --env-file=.env tools/db.mjs status''')+alert('SQLهای تکمیلی در این محیط روی PostgreSQL اجرا نشده‌اند. وجود Schema معتبر و build موفق به معنی migration تأییدشده نیست؛ پیش از دادهٔ واقعی تست DB فصل ۲۴ لازم است. هر تغییر SQL را version-control کن.'))
section('اجرای پایه و آزمون اتصال', '''<p>دو ترمینال در همان workspace باز کن:</p>'''+code('''# ترمینال اول
npx nx serve api''')+code('''# ترمینال دوم
npx nx serve web''')+'''<p>در سیستم محلی <code>http://localhost:4201</code> را باز کن. در محیط preview آدرس ارائه‌شدهٔ همان web را باز کن. browser فقط <code>/api/health</code> را صدا می‌زند. خروجی موفق <code>{"status":"ok","database":"ready"}</code> است؛ وقتی DB در دسترس نیست 503 با not-ready می‌گیری، نه اطلاعات محرمانهٔ اتصال.</p>'''+code('''# PowerShell، بررسی مستقیم API روی همان سیستم
Invoke-RestMethod http://localhost:3101/api/health''')+'''<p>این مرحله هنوز ماژول تجاری قابل استفاده تولید نکرده است. endpoint نمونهٔ generator در <code>/api</code> با guard محافظت شده؛ فقط health عمومی است. دادهٔ تست و کاربر مدیریتی واقعی خودکار ایجاد نمی‌شود.</p>''')
section('قرارداد مشترک API؛ قبل از نوشتن ماژول‌ها',table(['موضوع','قاعدهٔ لازم'],[['شناسه و مقدار','UUID به شکل string؛ Decimal و BigInt در JSON به شکل string؛ date-only به شکل YYYY-MM-DD میلادی؛ timestamp به شکل UTC ISO'],['DTO','بدنهٔ create/update فقط whitelist؛ بدون id، status اولیه، actor یا شمارهٔ سیستمی از کاربر. query page≥1، pageSize≤100 و ترتیب پایدار'],['Response','{items,total,page,pageSize} برای list؛ lookup فقط id/code/name/active؛ بدون spread کل entity یا PasswordHash'],['خطا','400 ورودی، 401 بدون هویت، 403 مجوز، 404 نبود/خارج scope، 409 نسخه/کلید تکراری، 422 قاعدهٔ دامنه'],['هم‌زمانی','expectedVersion اجباری برای فرمان تغییر؛ UPDATE WHERE Id AND Version؛ count=0 → 409؛ version در همان write افزایش یابد'],['ممیزی','actor از هویت معتبر سرور؛ reason و before/after محدود، correlationId و زمان UTC؛ نه از request body'],['حذف','deactivate یا transition؛ حذف فیزیکی اقلام مرجع استفاده‌شده مجاز نیست'],['امنیت','query پارامتری؛ role/data scope در سرور؛ cookie-based auth نیازمند CSRF و same-origin معتبر است؛ CORS=* با credential ممنوع']])+'''<p>برای توسعه، می‌توانی با service token محدود به آزمایش کار کنی؛ برای حساب‌های واقعی باید رابط <code>CurrentActor</code> و <code>PermissionPolicy</code> بسازی که از IdP معتبر یا هویت مستقل تازه تغذیه شود. جدول users در این Schema صرفاً مرجع مسئول است، مجوز ساخت پنل کامل Identity نیست. audit عمومی برای catalog/BOM/supplier باید از sink آزمایش یا درگاه مستقل طراحی شود؛ فقط برای Trading جدول trade_audit_events در allowlist داریم.</p>''')
section('دادهٔ پایه و ترتیب seed آزمایش', '''<p>Seed فقط دستی/آگاهانه و برای همین DB: ابتدا واحد، ارز، کشور و reference type/value موردنیاز؛ بعد واحد سازمانی و مالک/مسئول آزمایش؛ سپس itemها و profile؛ تأمین‌کننده و منابع تأمین؛ BOM؛ snapshot برنامه‌ریزی؛ در انتها پروژه و سربرگ سفارش.</p><p>برای جلوگیری از seed مخرب، از upsert روی کد normalized استفاده کن و هیچ deleteMany کلی ننویس. PasswordHash را از ERP کپی نکن؛ برای مرجع مسئول، کاربر seed غیرقابل ورود با PasswordHash=null کافی است، ولی تمام ستون‌های required فعلی users باید دادهٔ آزمایش معتبر داشته باشند.</p>'''+code('''// داخل یک seed script که از PrismaClient همین workspace استفاده می‌کند:
await db.referenceDataUnits.upsert({
  where: { NormalizedCode: 'EA' },
  update: {},
  create: {
    Code: 'EA', NormalizedCode: 'EA', NameFa: 'عدد', NameEn: 'Each',
    IsActive: true, SortOrder: 1, Version: 1n,
  },
});''','TypeScript — الگوی seed، نه اسکریپت مستقل آماده')+'''<p>ورودی‌های lookups را با Idهای واقعی seed به فرمان‌ها بده. Country و Currency را از دیتابیس اصلی import نکن مگر با تصمیم صریح و فایل دادهٔ غیرمحرمانهٔ مجاز. اگر مرجع واحد/ارز غیرفعال شد، از create جدید جلوگیری کن ولی snapshot تاریخی را بازنویسی نکن.</p>''')
section('محصول، قطعه و کامپوننت: یک هویت، profile جدا', '''<p>ابتدا <code>CatalogModule</code> با controller/DTO/service بنویس. سه CRUD موازی با شناسه و شمارهٔ ناسازگار نساز: <code>catalog.items</code> پایه است؛ PRODUCT با <code>products.ItemId</code> و PART/COMPONENT با <code>material_item_profiles.ItemId</code> تکمیل می‌شود.</p>'''+table(['API هدف — هنوز در recipe پیاده نشده','کار لازم'],[['GET /api/items?type=PRODUCT|PART|COMPONENT&search=&page=1&pageSize=25','فهرست سروری با filter و ترتیب BusinessNumber سپس Id'],['POST /api/items','نوع معتبر، نام فارسی، واحد فعال، category از reference type درست؛ item+profile در یک transaction'],['PUT /api/items/:id','expectedVersion، whitelist فیلدهای همان نوع؛ profile و item باهم'],['POST /api/items/:id/deactivate','reason و کنترل مصرف؛ حذف فیزیکی نکن']])+checklist(['شمارهٔ BusinessNumber سیستمی با prefixهای PRD-/PRT-/CMP- و sequence/counter اتمیک باشد؛ MAX+1 ممنوع.','برای ItemId محصول/پروفایل، همان Id قلم پایه را استفاده کن؛ UUID مستقل دوم نساز.','SafetyStockQty≥0، Scrap 0..100، ترتیب روزهای critical/safe/excess و supply method معتبر را تست کن.','واحد قلمی که BOM یا مصرف دارد بدون migration/کنترل تبدیل تغییر نکند.','شمارهٔ تکراری و غیرفعال‌سازی هم‌زمان را با unique و optimistic concurrency محافظت کن.']))
section('تأمین‌کننده و منبع تأمین مواد', '''<p><code>SupplierModule</code> فقط supplier، contacts و payment profile؛ <code>SourcingService</code> فقط اتصال قلم به منبع/قیمت برای همین برنامه‌ریزی. این مرحله سفارش خرید، حسابداری تأمین‌کننده، تحویل و رسید تولید نمی‌کند.</p>'''+table(['API هدف','قاعده'],[['GET/POST /api/suppliers و PUT /api/suppliers/:id','نام normalize‌شده، کشور و مالک معتبر، SupplierNumber سیستمی، expectedVersion'],['POST /api/suppliers/:id/contacts','حفظ یک تماس اصلی فعال؛ partial unique و transaction'],['PUT /api/suppliers/:id/payment-profile','PK مشترک SupplierId؛ payment term از نوع مرجع درست، نه هر reference value'],['GET/POST /api/items/:id/sources','supplier فعال، واحد پایهٔ item صحیح، lead time نامنفی، فقط یک preferred فعال'],['POST /api/sources/:id/prices','ارز فعال، مبلغ decimal، اعتبار تاریخی بازه؛ overwrite قیمت تاریخی ممنوع']])+'''<p>تست کن: supplier غیرفعال برای منبع جدید رد شود؛ دو درخواست هم‌زمان preferred فقط یکی موفق شوند؛ نسخهٔ قدیمی 409؛ قیمت‌های دو ارز بدون تبدیل ضمنی با هم جمع نشوند. شناسهٔ supplier در procurement را خودکار معادل trade_party بازرگانی فرض نکن.</p>''')
section('BOM: revision، line و applicability', '''<p>مدل‌های دقیق: bom_revisions + bom_lines + bom_item_applicabilities. در Draft ویرایش کن؛ Approval فرمان جدا با قفل والد و expectedVersion است. BOM تأییدشده immutable و اصلاح آن revision جدید است.</p>'''+table(['API هدف','توالی پیاده‌سازی'],[['GET /api/items/:id/bom-revisions','فقط revisionهای همان parent؛ page و status'],['POST /api/items/:id/bom-revisions','BaseOutputQty مثبت، واحد والد همان base unit، Draft و کد revision یکتا'],['PUT /api/bom-revisions/:id/lines','نسخهٔ Draft را قفل کن؛ usage>0، child معتبر، duplicate و self-link را رد کن'],['POST /api/bom-revisions/:id/approve','graph کامل را از snapshot بخوان؛ cycle مستقیم/غیرمستقیم، واحد، تطبیق profile و applicability را بررسی کن؛ سپس جایگزینی revision فعال در transaction'],['POST /api/bom-revisions/:id/obsolete','مجوز، reason، زمان/actor ممیزی؛ تاریخچه محفوظ']])+alert('یک child مشترک در دو شاخه cycle نیست؛ فقط حضور در مسیر فعال recursion cycle است. چک cycle فقط در حافظه بدون قفل انتشار هم‌زمان کافی نیست. partial unique تأییدشدهٔ هر والد باید در DB وجود داشته باشد.')+'''<p>نمونهٔ <code>explodeBom</code> آمادهٔ مطالعه و تست است. ضایعات در این مثال «افزایش مصرف» با ضریب <code>1 + percent/100</code> تعریف شده، نه yield با تقسیم بر <code>1-percent/100</code>. این تصمیم آزمایش باید پیش از هم‌ارزی با موتور فعلی تأیید شود؛ برابری دو موتور ادعا نشده است.</p>''')
section('برنامه‌ریزی مواد: ورودی محدود، نتیجهٔ قابل بازتولید', '''<p>API هدف <code>POST /api/material-planning/runs</code> با asOfDate، horizonEnd، demand، opening inventory، firm receipts و assumptionهای صریح است. منبع ورودی در این فاز می‌تواند فایل/adapter محدود باشد؛ ساخت کل forecast، ledger انبار، سفارش خرید یا تولید پیش‌نیاز تحمیلی نیست.</p>'''+checklist(['۱. تاریخ‌ها و horizon را validate کن؛ تمام مقدارها و واحدها را به base unit مشخص resolve کن. دادهٔ ناکامل را به صفر قطعی تبدیل نکن.','۲. در یک snapshot سازگار، item، BOM مصوب و ورودی‌ها را با engineVersion و زمان capture ذخیره کن؛ داده‌های زنده را بین روزها دوباره نخوان.','۳. run را با وضعیت اجرای مشخص و شناسهٔ مستقل بساز. از snapshotهای mrp_run_* استفاده کن؛ UUID مرجع بیرونی در snapshot مجوز ساخت ماژول بیرونی نیست.','۴. demand محصول را از BOM بشکن؛ intermediate و child مشترک را درست aggregate کن؛ مرز make/buy را با SupplyMethod نگه دار تا مصرف مصنوعی برای کالای خریدنی نسازی.','۵. برای هر روز: projected opening + receipt - gross؛ نیاز خالص max(0, gross+safety-opening-receipts). lead time و روز کاری را مستقل از تبدیل تاریخ نمایش محاسبه کن.','۶. نتیجهٔ روزانه، summary، trace منبع و exceptionها را با همان RunId ذخیره کن؛ اگر شکست رخ داد partial output را COMPLETED اعلام نکن.','۷. run موفق immutable باشد. اجرای مجدد run جدید می‌سازد؛ failed run باید علت و زمان و completeness واقعی داشته باشد.'])+code('''// فقط تابع خالصِ یک bucket؛ موتور زمان‌بندی کامل نیست:
netMaterial('100.25', '20', '10.1', '5'); // '75.15'
// gross + safety - onHand - firmReceipts; never below zero''','TypeScript')+'''<p>API خواندن: <code>GET /api/material-planning/runs/:id</code>، <code>.../:id/items</code>، <code>.../:id/items/:itemId/daily</code> و <code>.../:id/exceptions</code>. فیلترها فقط روی همان RunId. هیچ سفارش خرید/تولید خودکار از نتیجهٔ run نساز.</p>''')
section('کار برنامه‌ریز؛ بدون گسترش به What-if و سفارش', '''<p>سه جدول planner_saved_views، planner_work_items و planner_work_item_events فقط نمای ذخیره‌شده، پیگیری exception و تاریخچهٔ آن هستند. what_if_*، order_recommendations، delivery_schedules، route/certificate/outbox در این انتخاب نیستند.</p>'''+table(['API هدف','قاعده'],[['POST /api/material-planning/views','مالک از هویت سرور؛ filter schema محدود، نه SQL ذخیره‌شده'],['POST /api/material-planning/work-items','RunId/ExceptionId از همان run و scope؛ مسئول از lookup فعال'],['POST /api/material-planning/work-items/:id/assign یا /acknowledge','expectedVersion، actor و event در یک transaction؛ کنترل دسترسی داده'],['GET /api/material-planning/work-items/:id/events','تاریخچهٔ append-only با paging']])+'''<p>دکمه‌های تجاری این بخش در React ساخته نمی‌شوند. اگر کار جدید نیاز به جدول خارج allowlist داشت، اول تصمیم محدوده ثبت کن؛ آن را از روی روابط به‌صورت خودکار اضافه نکن.</p>''')
section('بازرگانی مرحلهٔ اول: فقط پروژهٔ اولیه', '''<p>قرارداد موجود ERP مرجع رفتار است؛ مدل Data Map مرجع ساختار آزمایش. ERP فعلی <code>trading.projects</code> دارد؛ Schema آزمایش <code>trading.trade_projects</code>. این دو یک دیتابیس یا یک migration نیستند.</p>'''+table(['ورودی API هدف POST /api/trading/project-setup','نگاشت آزمایش'],[['titleFa / notes','trade_projects.titleFa / notes؛ سقف فعلی 250 / 4000 در DTO'],['startDate','project_stages.startedAt برای PROJECT_SETUP؛ registrationDate تاریخ ثبت سیستمی است و جای startDate کاری نیست'],['customerId','customerPartyId و lookup طرف دارای نقش CUSTOMER؛ trade_party_roles فقط برای lookup'],['businessCardId','businessCardId؛ کارت فعال معتبر، نه ساخت کل چرخهٔ پروانه/کارت'],['responsibleUserId','مسئول فعال از lookup مرکزی محدود؛ lookup نباید PasswordHash/Email مدیریتی برگرداند'],['سیستمی','projectNumber، actor، DRAFT، createdAt، version؛ نه از request body']])+'''<p>پروژه، نگاشت تاریخ شروع و audit را اتمیک ذخیره کن. فیلد اولویت، عنوان انگلیسی، تأمین‌کننده، تاریخ هدف، کد هشت‌رقمی، lock و مراحل بعد را فقط چون در جدول منبع آمده‌اند به DTO اضافه نکن. هیچ order خودکار ساخته نمی‌شود.</p><p>منابع رفتار فعلی در <code>main-erp/docs/ui/trading-stage-1/README.md</code> است. مشتری و کارت در ERP از reference_values قبلی می‌آیند؛ انتقال خودکار آن‌ها به TradeParty یا BusinessCard جزو این راهنما نیست.</p>''')
section('بازرگانی مرحلهٔ دوم: سربرگ ثبت سفارش',table(['API هدف','رفتار فعلی موردنیاز'],[['GET /api/trading/projects/:id/order-registrations','جست‌وجوی شماره، وضعیت و pageSize=25؛ فقط همان پروژه'],['POST /api/trading/order-registrations','projectId، orderNumber، registrationDate، currencyId، declaredValueAmount و notes'],['PUT /api/trading/order-registrations/:id','فقط Draft، پروژهٔ باز، expectedVersion، reason؛ projectId قابل انتقال نیست'],['POST /api/trading/order-registrations/:id/status','فرمان جدا با دلیل؛ تغییر وضعیت سفارش مستقل از پروژه'],['GET /api/trading/order-registrations/:id/history','رخدادهای append-only همین سفارش با مجوز view']])+'''<p>نگاشت: RegistrationNumber فعلی → orderNumber منبع؛ RegisteredAmount → declaredValueAmount؛ currencyId منبع یک فیلد متنی است که هنوز FK صریح به reference_data ندارد. برای آزمایش فقط شناسهٔ ارز resolveشده را ذخیره و صریحاً validate کن؛ تصمیم افزودن FK/تغییر native type باید در overlay ثبت شود، نه حدس نام فیلد.</p>'''+checklist(['مبلغ string مثبت با حداکثر ۱۸ رقم صحیح و ۶ اعشار؛ Number/parseFloat برای مبلغ ممنوع.','شمارهٔ سفارش یکتای سراسری حتی برای CANCELLED؛ استفادهٔ مجدد مجاز نیست.','notes سقف فعلی ۲۰۰۰؛ reason در audit، نه جایگزین notes.','ارز غیرفعال برای انتخاب جدید رد شود؛ ویرایش بدون تغییر همان ارز تاریخی سیاست حفظ snapshot داشته باشد. Map به‌تنهایی تمام snapshotهای فعلی را ندارد؛ گسترش ستونی لازم را پیش از parity طراحی و ثبت کن.','هیچ order_registration_lines، order_permits، نرخ/تبدیل ارز، بانک، اینکوترم یا روش پرداخت را در این مرحله expose نکن.','FX این فاز ساخته نمی‌شود. برای دیتابیس تازه linkedFx وجود ندارد؛ اگر adapter بیرونی بعداً اضافه شد، نبود پاسخ را false فرض نکن و read/check/attach باید همان قفل ردیف را رعایت کنند.'])+'''<p>نمونهٔ حالت‌ها و کنترل ویرایش در domain.logic.ts آمده است؛ رفتار هم‌ارز کامل فقط پس از تست PostgreSQL و همسان‌سازی snapshotها قابل ادعاست.</p>''')
section('الگوی transaction و قفل؛ چطور service بنویسی؟', '''<p>برای هر command: مجوز → DTO → transaction → lock/expectedVersion → اعتبار مراجع و قواعد → write → audit → commit → response محدود. Controller نباید <code>data: body</code> را مستقیم به Prisma بدهد.</p>'''+code('''// الگوی سرویس، نه endpoint آماده؛ ورودی‌ها از DTO معتبر آمده‌اند.
await db.$transaction(async tx => {
  const rows = await tx.$queryRaw<{id:string,version:number}[]>`
    SELECT id, version FROM trading.order_registrations
    WHERE id = ${orderId}::uuid FOR UPDATE`;
  if (!rows.length) throw notFound();
  assertVersion(expectedVersion, String(rows[0].version));
  // project status + identity scope + any external linkage: re-check under lock.
  // updateMany WHERE { id, version } with explicit fields, version increment.
  // append trade_audit_events for this order inside THIS transaction.
  // count !== 1 => conflict; throwing rolls back both writes.
}, { isolationLevel: 'Serializable' });''','TypeScript — pseudo-service؛ notFound/DTO/audit را پیاده کن')+'''<p>Serializable ممکن است P2034 بدهد: retry محدود فقط برای خطای retryable و فرمان idempotent با request key معتبر. unique violation را بی‌قید retry نکن. P2002 → conflict، P2003 → مرجع نامعتبر، P2025 → not found/conflict با قرارداد مشخص؛ متن خام SQL را به کاربر نده.</p><p>برای شماره‌گذاری، sequence یا counter با lock؛ MAX(number)+1 با تست تکی هم ناامن است. برای اجرای run طولانی transaction را در تمام محاسبه باز نگه ندار؛ snapshot را capture کن، محاسبهٔ خالص را انجام بده و نتیجه را با وضعیت صحیح منتشر کن.</p>''')
section('تست‌های قابل اجرا و دروازهٔ پایان هر برش',code('''npx nx run-many -t build -p api web --skip-nx-cache
npx nx test api --runInBand --skip-nx-cache''')+'''<p>در scaffold بررسی‌شده: هر دو build موفق، ۲۴ تست در ۳ suite موفق (۲ تست scaffold + ۲۲ case دامنه). این نتیجه integration DB، migration، احراز هویت واقعی یا APIهای تجاری را ثابت نمی‌کند.</p>'''+table(['مرحله','تست تکمیلی لازم که باید بنویسی'],[['Catalog / supplier','CRUD با PostgreSQL، FK، partial unique هم‌زمان، profile مشترک، نسخهٔ stale و غیرفعال بودن مرجع'],['BOM','cycle مستقیم/غیرمستقیم، child مشترک مجاز، rollback Approval، انتشار concurrent و immutability'],['MRP','چند روز، carry-forward stock، receipt، safety، lead time، rounding واحد، دادهٔ ناقص، تکرارپذیری snapshot و trace'],['Trading','شماره تکراری، پروژه بسته، مبلغ دقیق، version conflict، backward correction و reason، atomic audit، دادهٔ خارج scope'],['Security','401 بدون credential، 403 مجوز ناکافی، عدم افشای کاربران/secret، guard پیش‌فرض روی مسیر جدید'],['Database','ایجاد DB از صفر، deploy SQL مکمل، rollback فرمان شکست‌خورده، actual row locks و migration status']])+alert('برای integration DB، سرویس/DB آزمایش جدا با نام hadron_nx_test و پورت 5545 بساز؛ helper فقط همین جفت یا lab/5544 را می‌پذیرد. آدرس lab یا main را در تستی که truncate/پاک‌سازی دارد استفاده نکن. .env.test را با secret تازه بساز و runner با --env-file=.env.test اجرا شود؛ پایگاه تست در این بسته خودکار ساخته نشده است.'))
section('مسیر ادامهٔ کار؛ هر بار فقط یک برش',table(['ترتیب','کار قابل تحویل / شرط عبور'],[['۱','scaffold، env، DB مستقل، migration بازبینی‌شده، health سبز و guard بسته'],['۲','lookupهای حداقلی و item+profile؛ تست API و DB قبل از رفتن به supplier'],['۳','supplier/contact/payment و sourcing؛ بدون PO و ledger'],['۴','BOM draft/lines/approve؛ قفل، unique و graph test'],['۵','MRP snapshot/input/engine/results؛ بدون سفارش خودکار و بدون موتور ساخت/مسیر'],['۶','کار برنامه‌ریز و view ذخیره‌شده؛ بدون what-if'],['۷','پروژهٔ اولیهٔ Trading و audit؛ فقط فیلدهای مرحلهٔ اول'],['۸','سربرگ سفارش، ویرایش و transition؛ بدون line/permit/FX'],['۹','integration، security و تصمیم‌های باز Schema؛ بعداً و فقط با درخواست جدید سراغ صفحات React برو']])+'''<p>برای هر برش سه فایل اصلی DTO/controller/service و تست domain+integration بساز؛ از domain.logic.ts فقط بخش مرتبط را استفاده کن. پوشه‌ها را می‌توانی در <code>apps/api/src/modules/catalog|suppliers|bom|material-planning|trading</code> نگه داری؛ بزرگ‌شدن کد دلیل اضافه‌کردن حوزهٔ تجاری جدید نیست. اگر آن‌ها را Nx library کردی، tags دامنه و module boundary را اعمال کن و reference adapterها را در shared محدود قرار بده.</p>''')
section('خطایابی، اجرا و محدودیت‌های تحویل',table(['نشانه','اقدام'],[['Schema validate شکست می‌خورد','نسخهٔ دقیق Prisma و config را بررسی کن؛ latest یا url داخل datasource Prisma 7 نگذار'],['Engine download / TLS error','این محیط محدودیت دانلود binary دارد؛ در سیستم خود دسترسی رسمی Prisma را بررسی کن. validate ما با wasm و bypass فقط برای binary استفاده‌نشده انجام شد؛ این bypass دستور کاربر یا راه‌حل migration نیست'],['Port 5544 اشغال / password auth failed','خروجی compose ps، env همین آزمایش و volume همین پروژه را بررسی کن؛ به DB اصلی سوییچ نکن'],['web not-ready یا 503','API روی 3101، DB روی 5544، proxy /api و cwd workspace را بررسی کن؛ localhost در کد browser نگذار'],['Unknown BigInt serialization','response DTO صریح و تبدیل BigInt/Decimal به string؛ تغییر global BigInt.prototype نده'],['Nx graph یا stale cache','nx reset فقط cache Nx را پاک می‌کند؛ با reset Git یا Prisma اشتباه نکن؛ سپس regenerate و build'],['لاگ‌های helper ویندوز','مسیرهای source repository و application اکنون جدا هستند؛ backup/restore این محیط runtime-tested نیست؛ برای استفادهٔ حساس اول staging']])+'''<p>بررسی انجام‌شده: scaffold Nx، Prisma validate + generate، build API/Web و ۲۴ تست نمونه؛ اپ قبلی پس از انتقال build موفق و ۳۲۳ تست frontend موفق با Node 26. اجرای .NET، Docker، migration/SQL و integration PostgreSQL انجام نشده است. در راهنما هیچ API تجاری طرح‌شده «از قبل آماده» معرفی نشده است.</p>''')
