js='''document.querySelectorAll('.copy').forEach(button=>button.addEventListener('click',async()=>{const text=button.parentElement.querySelector('code').textContent;try{await navigator.clipboard.writeText(text);button.textContent='کپی شد'}catch{const a=document.createElement('textarea');a.value=text;document.body.append(a);a.select();document.execCommand('copy');a.remove();button.textContent='کپی شد'}setTimeout(()=>button.textContent='کپی',1500)}));document.getElementById('model-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.model').forEach(x=>x.hidden=!x.dataset.search.toLowerCase().includes(q))});document.getElementById('download-schema').addEventListener('click',()=>{const bytes=Uint8Array.from(atob(document.getElementById('schema-data').textContent),c=>c.charCodeAt(0));const u=URL.createObjectURL(new Blob([bytes],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='schema.prisma';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.filter(e=>e.isIntersecting).forEach(e=>{document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))})},{rootMargin:'0px 0px -70% 0px'});document.querySelectorAll('section[id]').forEach(s=>observer.observe(s))}'''
result='<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hadron · راهنمای ساخت بک‌اند محدود Nx ERP Lab</title><style>'+css+'</style></head><body><aside class="nav"><div class="brand" dir="ltr">HADRON / LAB</div><small>دفترچهٔ اجرایی · نسخهٔ ۱ · ۲۰۲۶/۱۰/۱۸</small><nav>'+nav+'</nav></aside><main><header class="hero"><div class="eyebrow" dir="ltr">IMPLEMENTATION PLAYBOOK · BACKEND FIRST</div><h1>از Data Map منتخب<br>تا بک‌اند مستقل Nx</h1><p>دستورهای ساخت، Schema محدود، قرارداد API، قواعد دامنه و مسیر آزمون؛ فقط برای بخش‌های تأییدشدهٔ هادرون، بدون تحمیل کل ERP و بدون صفحات تجاری React.</p><div class="pills"><span>Nx 23.3</span><span>NestJS 11</span><span>Prisma 7.10.1</span><span>PostgreSQL 18</span><span>React shell only</span></div></header><div class="stats"><div class="stat"><strong>42 / 180</strong><small>جدول انتخاب‌شده، نه کل نقشه</small></div><div class="stat"><strong>29 + 13</strong><small>دامنه/snapshot + پشتیبان</small></div><div class="stat"><strong>0</strong><small>صفحهٔ عملیاتی React</small></div><div class="stat"><strong>'+str(len(sections))+'</strong><small>فصل و پیوست آفلاین</small></div></div>'+content+'<div class="footer">ساخت آزمایش جدید ≠ مهاجرت ERP فعلی · اصل منابع محفوظ · بدون اتصال به دیتابیس main-erp</div></main><script id="schema-data" type="text/plain">'+schema_b64+'</script><script>'+js+'</script></body></html>'
